const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const SAVE_KEY='little-stone-club-v1';
let storageOK=true;
function load(){try{const s=JSON.parse(localStorage.getItem(SAVE_KEY));if(s?.version===1&&Array.isArray(s.stones)&&s.stones.length&&s.stones.every(x=>TYPES[x.id]&&Number.isFinite(x.mass)&&x.mass>0&&x.radius>0&&Array.isArray(x.genes)&&x.genes.length===4)&&Number.isFinite(s.credits)&&Number.isFinite(s.best)){s.map=clamp(s.map||0,0,4);s.discovered=s.discovered||[...new Set(s.stones.map(x=>x.id))];s.history=s.history||[];s.totalThrows=s.totalThrows||0;return s;}}catch{}return {version:1,credits:360,best:0,bestDistance:0,totalThrows:0,map:0,stones:[makeStone(0,false),makeStone(4,false),makeStone(7,false)],selected:null,discovered:[0,4,7],history:[],sound:false};}
const state=load();state.selected=state.stones.find(s=>s.uid===state.selected)?.uid||state.stones[0].uid;
let preferences=readSettings(state.sound);const audio=new GameAudio(preferences);
let mode='explore',map=MAPS[state.map],landscape=makeLandscape(map),player={x:151,y:190},target=null,loot=[],keys={},time=0,moving=false,sim=null,camera=0,charging=false,chargeTime=0,chargePower=.65,resultAt=0,resultShown=false,modalBusy=false,toastTimer,collectionFilter='all',soundFinished=false;
const canvas=$('#game'),ctx=canvas.getContext('2d'),modal=$('#modal');ctx.imageSmoothingEnabled=false;
