function draw(){ctx.setTransform(2,0,0,2,0,0);ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,480,235);ctx.drawImage(landscape,0,0);ambient(ctx,preferences.reducedMotion?0:time,map,mode);if(mode==='explore'){const near=nearest();for(const l of loot){drawStone(ctx,TYPES[l.id],l.x,l.y,.38);if(!preferences.reducedMotion&&Math.sin(time*2+l.phase)>.6){ctx.fillStyle='#f3ecb9';ctx.fillRect(l.x+6,l.y-6,1,5);ctx.fillRect(l.x+4,l.y-4,5,1);}if(near?.type==='stone'&&near.uid===l.uid){ctx.strokeStyle='#e9ecc5';ctx.lineWidth=1;ctx.strokeRect(Math.round(l.x-9),Math.round(l.y-7),18,12);}}
 const entities=[{y:player.y,draw:()=>drawPlayer(ctx,player.x,player.y,time,moving)},{y:190,draw:()=>{drawStone(ctx,TYPES[map.npcStone],285,190,.7,true);ctx.fillStyle='#f0efcf';ctx.fillRect(279,168,12,10);ctx.fillStyle='#6f8264';ctx.font='bold 7px monospace';ctx.fillText('···',279,174);ctx.fillStyle='#f0efcf';ctx.fillRect(282,178,3,2);}}];entities.sort((a,b)=>a.y-b.y).forEach(e=>e.draw());ctx.font='6px "Noto Sans SC",sans-serif';ctx.textAlign='center';ctx.fillStyle='#f4f2d6';ctx.shadowColor='#486746';ctx.shadowBlur=2;ctx.fillText('你',player.x,player.y+12);ctx.shadowBlur=0;ctx.textAlign='left';
 }else{drawPlayer(ctx,37,201,time,false,charging||!!sim);const baseline=172,scaleX=11,scaleY=24;ctx.strokeStyle='#d4e4bf';ctx.lineWidth=1;ctx.beginPath();for(let px=53;px<480;px+=2){const h=sim?sim.water.sample(camera+(px-53)/scaleX).height:Math.sin(px*.06+time)*map.wave;const y=baseline-h*scaleY;px===53?ctx.moveTo(px,y):ctx.lineTo(px,y);}ctx.stroke();ctx.font='5px monospace';for(let x=Math.ceil(camera/10)*10;x<camera+42;x+=10){const px=53+(x-camera)*scaleX;if(px<52)continue;ctx.fillStyle='#d4e3c088';ctx.fillRect(px,179,1,3);ctx.fillStyle='#d6e6c9';ctx.fillText(x+'m',px-3,190);}
 if(sim){ctx.strokeStyle=preferences.trajectory?'#f6e6b4aa':'transparent';ctx.setLineDash([2,3]);ctx.beginPath();sim.trail.forEach((p,i)=>{const x=53+(p.x-camera)*scaleX,y=baseline-p.y*scaleY;i===0?ctx.moveTo(x,y):ctx.lineTo(x,y);});ctx.stroke();ctx.setLineDash([]);for(const [i,contact]of sim.contacts.entries()){const age=sim.time-contact.time,x=53+(contact.x-camera)*scaleX;if(x<45||x>490)continue;ctx.strokeStyle=`rgba(239,244,209,${Math.max(.1,1-age*.55)})`;ctx.beginPath();ctx.ellipse(x,baseline,4+Math.min(age,2)*9,1.5+Math.min(age,2)*2,0,0,Math.PI*2);ctx.stroke();if(contact.success){ctx.fillStyle='#f1edc9';ctx.font='7px monospace';ctx.fillText(String(i+1),x-1,baseline-10);}if(age<.5){for(let j=0;j<5;j++){const xx=x+(j-2)*age*15,yy=baseline-Math.sin(age/.5*Math.PI)*(5+j%3*3);ctx.fillStyle='#e8f0d0';ctx.fillRect(xx,yy,1,2);}}}if(!sim.done){const x=53+(sim.x-camera)*scaleX,y=baseline-sim.y*scaleY;ctx.save();ctx.translate(x,y);ctx.rotate(-sim.tilt);drawStone(ctx,equipped(),0,0,.27);ctx.restore();}}
 else{const power=charging?chargePower:.6,speed=5+power*12,angle=+$('#pitch').value*Math.PI/180;ctx.fillStyle='#f9efc3aa';for(let t=0;preferences.trajectory&&t<.45;t+=.055){const x=70+speed*Math.cos(angle)*t*scaleX,y=baseline-(.48+speed*Math.sin(angle)*t-4.905*t*t)*scaleY;if(y>baseline)break;ctx.fillRect(x,y,1,1);}drawStone(ctx,equipped(),46,185,.35);}}
}
let last=performance.now(),lastDraw=0;function frame(now){const dt=Math.min((now-last)/1000,.05);last=now;if(!document.hidden){update(dt);if(now-lastDraw>=1000/preferences.renderRate-1){draw();lastDraw=now;}}requestAnimationFrame(frame);}spawnLoot();applyPreferences(preferences);audio.setMap(map.id);renderPocket();save();requestAnimationFrame(frame);
document.addEventListener('pointerdown',()=>audio.unlock(),{capture:true});document.addEventListener('keydown',()=>audio.unlock(),{capture:true});document.addEventListener('click',e=>{if(e.target.closest('button')&&!e.target.closest('[data-audition],#throwBtn,#soundBtn'))audio.event('ui');},{capture:true});window.addEventListener('storage',e=>{if(e.key===SETTINGS_KEY){preferences=readSettings();audio.apply(preferences);document.body.classList.toggle('reduced-motion',preferences.reducedMotion);document.body.classList.toggle('no-hints',!preferences.hints);renderHeader();}});

